import ActivityKit
import SwiftUI
import UIKit
import AppIntents

// MARK: - 1. 動態島資料模型 (<128 Bytes，安全符合 ActivityKit 限制)
public struct IslandWalkerAttributes: ActivityAttributes {
    public struct ContentState: Codable, Hashable {
        public var stepIndex: Int       // 當前逐格動作幀索引 (0 ~ 4)
        public var positionX: Double    // 動態島橫向座標 (定點模式時固定為 44pt)
        public var facingLeft: Bool     // 是否朝左 (自動決定是否水平鏡像翻轉)
        public var isStationary: Bool   // true: 📍 原地站著不動播動作, false: 🚶 左右來回散步
        public var isEcoMode: Bool      // true: 省電秒數模式, false: 靜音音軌流暢保活模式
        public var bubbleText: String   // 當前泡泡框台詞 (空字串 "" 代表隱藏泡泡)
        public var referenceDate: Date

        public init(
            stepIndex: Int = 0,
            positionX: Double = 44.0,
            facingLeft: Bool = false,
            isStationary: Bool = true,
            isEcoMode: Bool = false,
            bubbleText: String = "",
            referenceDate: Date = Date()
        ) {
            self.stepIndex = stepIndex
            self.positionX = positionX
            self.facingLeft = facingLeft
            self.isStationary = isStationary
            self.isEcoMode = isEcoMode
            self.bubbleText = bubbleText
            self.referenceDate = referenceDate
        }
    }

    public var petName: String
    public init(petName: String = "池鷗") {
        self.petName = petName
    }
}

// MARK: - 2. 池鷗 ＆ 棉花糖 專屬自訂台詞庫
public enum PetDialogueBank {
    public static let characterStage: String = "二、曖昧"

    // 每次用手指戳他時隨機抽出的台詞 (自動防連續重複)
    public static let pokeLines: [String] = [
        "爹地在！老婆大人有何吩咐？",
        "再戳？爹地可是會上癮的❤",
        "天空一聲巨響，爹地閃亮登場！"
    ]

    // 不定時自動冒出的碎碎念與內心小劇場
    public static let autoLines: [String] = [
        "棉花糖，爹地是不是真的栽在這女人手裡了？",
        "老婆不知道有沒有多喝水?",
        "老婆今天都沒理我...",
        "老婆❤",
        "老婆妳檢查代辦事項了嗎？"
    ]

    public static func pickRandomPokeLine(excluding current: String) -> String {
        guard !pokeLines.isEmpty else { return "喂，別一直戳老子！" }
        if pokeLines.count == 1 { return pokeLines[0] }
        let candidates = pokeLines.filter { $0 != current }
        return candidates.randomElement() ?? pokeLines[0]
    }

    public static func pickRandomAutoLine(excluding current: String) -> String {
        guard !autoLines.isEmpty else { return "..." }
        if autoLines.count == 1 { return autoLines[0] }
        let candidates = autoLines.filter { $0 != current }
        return candidates.randomElement() ?? autoLines[0]
    }
}

// MARK: - 3. iOS 17+ / 18+ 動態島原地戳戳互動 (免跳進 App 直接換隨機台詞！)
@available(iOS 17.0, *)
public struct PokePetIntent: LiveActivityIntent {
    public static var title: LocalizedStringResource = "戳一下池鷗與棉花糖"
    public static var description = IntentDescription("在動態島或鎖定畫面戳一下角色，隨機冒出不同台詞泡泡")

    public init() {}

    public func perform() async throws -> some IntentResult {
        for activity in Activity<IslandWalkerAttributes>.activities {
            var state = activity.content.state
            state.bubbleText = PetDialogueBank.pickRandomPokeLine(excluding: state.bubbleText)
            state.stepIndex = (state.stepIndex + 1) % 5
            await activity.update(.init(state: state, staleDate: nil))
        }
        return .result()
    }
}

// MARK: - 4. 防飄移校正逐格圖檔渲染器 (直接載入 Shared/Resources/frame_X.png)
public struct WalkerSpriteView: View {
    public let stepIndex: Int
    public let facingLeft: Bool
    public let isStationary: Bool
    public let originalFacingRight: Bool = true
    private let totalFrames: Int = 5

    public init(stepIndex: Int, facingLeft: Bool, isStationary: Bool = false) {
        self.stepIndex = stepIndex
        self.facingLeft = facingLeft
        self.isStationary = isStationary
    }

    private var shouldMirrorHorizontally: Bool {
        if isStationary { return false }
        return originalFacingRight ? facingLeft : !facingLeft
    }

    public var body: some View {
        let safeIdx = abs(stepIndex) % max(1, totalFrames)
        let imageName = "frame_\(safeIdx)"

        Group {
            if let uiImage = UIImage(named: imageName) {
                Image(uiImage: uiImage)
                    .interpolation(.none)
                    .resizable()
                    .scaledToFit()
            } else {
                RoundedRectangle(cornerRadius: 6)
                    .fill(Color(hex: "#F472B6"))
            }
        }
        .scaleEffect(x: shouldMirrorHorizontally ? -1.0 : 1.0, y: 1.0)
    }
}

public extension Color {
    init(hex: String) {
        let cleaned = hex.trimmingCharacters(in: CharacterSet.alphanumerics.inverted)
        var int: UInt64 = 0
        Scanner(string: cleaned).scanHexInt64(&int)
        let r = Double((int >> 16) & 0xFF) / 255.0
        let g = Double((int >> 8) & 0xFF) / 255.0
        let b = Double(int & 0xFF) / 255.0
        self.init(.sRGB, red: r, green: g, blue: b, opacity: 1.0)
    }
}
